#include <iostream>
#include <string>
#include <array>
#include <iomanip>
#include <cstddef>

// Fig. 22.2: Dinh nghia struct Card gom hai thuoc tinh face va suit
struct Card {
    std::string face;
    std::string suit;
};

// Section 22.3: typedef truyen thong va using hien dai (C++17)
typedef Card* CardPtr;
using ModernCardPtr = Card*;

// Minh hoa can bien bo nho va padding hole (Fig. 22.1)
struct Example {
    char c; // 1 byte
    // 3 bytes padding (hole) tren he thong 32/64-bit de int can bien 4 bytes
    int i;  // 4 bytes
};

// Fig. 22.2 - 22.3: Lop mo phong bo bai DeckOfCards su dung Card struct
class DeckOfCards {
public:
    static const int numberOfCards = 52;
    static const int faces = 13;
    static const int suits = 4;

    DeckOfCards() {
        static const std::string suitNames[suits] = {
            "Hearts", "Diamonds", "Clubs", "Spades"
        };
        static const std::string faceNames[faces] = {
            "Ace", "Deuce", "Three", "Four", "Five", "Six", "Seven",
            "Eight", "Nine", "Ten", "Jack", "Queen", "King"
        };

        for (size_t i = 0; i < deck.size(); ++i) {
            deck[i].face = faceNames[i % faces];
            deck[i].suit = suitNames[i / faces];
        }
    }

    // Thuat toan xao bai xac dinh (deterministic swap de kiem thu)
    void shuffleDeterministic() {
        for (size_t i = 0; i < deck.size(); ++i) {
            size_t j = (i * 37 + 11) % numberOfCards; // Cong thuc hoan vi mau
            Card temp = deck[i];
            deck[i] = deck[j];
            deck[j] = temp;
        }
    }

    // Chia va hien thi 4 la bai dau tien de minh hoa xuat cot dinh dang
    void dealSample(size_t count) const {
        for (size_t i = 0; i < count && i < deck.size(); ++i) {
            std::cout << std::right << std::setw(5) << deck[i].face << " of "
                      << std::left << std::setw(8) << deck[i].suit
                      << ((i + 1) % 2 ? "\t" : "\n");
        }
    }

private:
    std::array<Card, numberOfCards> deck;
};

int main() {
    // 1. Kiem tra kich thuoc can bien va padding cua struct Example
    std::cout << "sizeof(Example): " << sizeof(Example) << " bytes\n";
    std::cout << "Offset of c: " << offsetof(Example, c) << ", Offset of i: "
              << offsetof(Example, i) << "\n";

    // 2. Kiem tra su dung Card qua pointer alias
    Card singleCard{"Ace", "Spades"};
    CardPtr pLegacy = &singleCard;
    ModernCardPtr pModern = &singleCard;
    std::cout << "Single Card: " << pLegacy->face << " of " << pModern->suit << "\n";

    // 3. Khoi tao va mo phong chia bai DeckOfCards
    DeckOfCards deck;
    deck.shuffleDeterministic();
    std::cout << "Sample dealt cards:\n";
    deck.dealSample(4);

    return 0;
}
